    V.append(dict(source='JOIN',es_id='ES10',release='JOIN v10',table_or_object='JOIN survey-level indicator database',variable=str(c),label_or_definition=lab or str(c),storage_type=str(df[c].dtype),role='selected_dimension' if c in ['Labor Force Participation Rate, aged 15-64','Female Labor Force Participation Rate, aged 15-64','Employment to Population Ratio, aged 15-64','Employment Rate, aged 15-64 ','Unemployment Rate, aged 15-64','Youth Unemployment Rate, aged 15-24','Wage employees, aged 15-64 ','Self-employed, aged 15-64','Unpaid, aged 15-64','Employers, aged 15-64','Share of informal jobs, aged 15-64',' Agriculture, aged 15-64',' Industry, aged 15-64',' Services, aged 15-64','Average weekly working hours','Median Earnings for wage workers per hour, local nominal currency','Real Median Hourly  Wages in USD (base 2011), PPP adjusted','Total flags in survey','Percentile (100 = max), total flags'] else ('key' if c in ['Country Name','Country Code','Year of survey','Survey Data Source','Subsample'] else 'metadata'),value_label_present='no',unit_or_scale=('count/share/rate/currency/hours depending on label' if c not in ['Country Name','Country Code','Region Code','Subsample','Income Level Name','Income Level Code','Year of survey','Survey Data Source','Survey Type'] else ''),classification_or_denominator=('working-age population or workers as named in label' if 'aged 15' in str(c) else ''),missing_or_special_states='empty cells treated as absent; no automatic zero',docs_ref='JOIN Manual and Sheet2 definition',availability='observed',profile_scope='complete_metadata_census',notes='Header-derived variable name; definition from Sheet2 where matched'))
